-- =============================================================================
-- 0019 VIDEO LISTENING ACTIVITIES (generated by scripts/build-content.mts from
-- content/videos.mts). YouTube songs embedded via youtube-nocookie, with
-- questions. Needs 0015, 0016. Inserts only missing rows.
-- =============================================================================
do $$
declare
  v_topic uuid;
