    insert into public.practice_activities (topic_id, kind, title_en, title_vi, sort_order, status, content)
    select v_topic, 'listening', 'Watch and answer', 'Xem video và trả lời', 200, 'published', '{"media":{"source":"youtube","videoId":"jYAWf8Y91hA"},"items":[{"type":"tf","sentence":"This song is about colours.","answer":true,"emoji":null},{"type":"mc","question":"Which colour is in the song?","answer":"purple","options":["purple","black","brown"],"emoji":null},{"type":"tf","sentence":"The song says “I see something blue”.","answer":true,"emoji":null},{"type":"mc","question":"What is the first colour?","answer":"blue","options":["blue","green","white"],"emoji":null}]}'::jsonb
